    if (!inv || !a || !racine.classList.contains("dcc-maquette")) { if (ap) ap.remove(); if (inv && inv.hasAttribute("data-dcc-appareil")) inv.removeAttribute("data-dcc-appareil"); return; }
    // (v0.113.1 : le panneau garde sa place sous la rangée des sacs)
    if (!inv.hasAttribute("data-dcc-appareil")) inv.setAttribute("data-dcc-appareil", "");
    if (!ap) { ap = el("div", "dcc-appareil"); ap.setAttribute("aria-hidden", "true"); ap.append(el("span", "dcc-ap-r"), el("span")); inv.appendChild(ap); }
    var sp = ap.lastChild, texte = a.n + " / " + a.max + (a.plein ? " · plein" : a.quand ? " · " + a.quand : "");
    if (sp.textContent !== "Neuvopack · " + texte) { sp.textContent = ""; sp.append(el("b", null, "Neuvopack"), document.createTextNode(" · " + texte)); }
    if (ap.style.getPropertyValue("--dcc-p") !== String(a.part)) ap.style.setProperty("--dcc-p", String(a.part));
