    var nom = ((l.querySelector("span.couleur4") || {}).textContent || "").trim(), alerte = !!l.querySelector(".orange");
    var texte = l.textContent.replace(/\[ALERTE\]/g, " ").replace(/\s+/g, " ").trim();
