  function commandeDeck(nom) { var n = String(nom || "").toLowerCase(); for (var i = 0; i < COMMANDES_DECK.length; i++) if (COMMANDES_DECK[i][0].toLowerCase() === n) return COMMANDES_DECK[i]; return null; }
  // Tes UBA en informatique, lus dans ta fiche : la sixième compétence (#statistiques .stat_6_entier et .stat_6_decimal, copie
