    if (!sp) { sp = el("span", "dcc-deck-serie"); sp.title = "Entraînement (cours AADSS) : 5 commandes, quit, 5 commandes, quit"; barre.insertBefore(sp, barre.children[1] || null); }
    ecrireSiChange(sp, (s.n >= 5 ? "Série 5/5 : quit maintenant" : "Série " + s.n + "/5") + (s.faites ? " · " + s.faites + " faite" + (s.faites > 1 ? "s" : "") : ""));
