      (d && Array.isArray(d.liste) ? d.liste : []).forEach(function (c) { if (!c || typeof c.nom !== "string") return; var r = ligneSure(c.relation); if (c.nom && r && !/^aucun$/i.test(r)) relationsDeck[cleNom(c.nom)] = r.toLocaleLowerCase("fr"); });
